INSERT INTO products(category_id,name,slug,brand,description,images,featured,pinned,sort_order,created_at) VALUES((SELECT id FROM categories WHERE slug='tai-nghe'),'Tai nghe không dây Studio H1','studio-h1','OD. Audio','Âm thanh cân bằng, chống ồn chủ động và cảm giác đeo nhẹ nhàng. Pin lên đến 40 giờ, kết nối Bluetooth 5.3 và sạc nhanh USB-C. Đi cùng bạn từ góc làm việc đến chuyến đi cuối tuần.','["images/headphones.jpg","images/desk.jpg"]',1,1,0,NOW());
